"""Reproducible synthetic datasets generated by the particle simulator."""

from __future__ import annotations

import json
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Any, NamedTuple

import numpy as np

from .config import InputBounds, ParticleConfig, ReactorConfig, SamplingConfig, SimulationConfig
from .simulator import simulate_batch

FEATURE_NAMES = (
    "peak_temperature",
    "residence_time",
    "hydrogen_concentration",
    "diameter",
    "initial_oxide_fraction",
)
TARGET_NAMES = ("final_oxide_fraction", "maximum_temperature")
SPLIT_NAMES = ("train", "validation", "test", "ood")


class DatasetSplit(NamedTuple):
    """Feature and target matrices for one named dataset split."""

    features: np.ndarray
    targets: np.ndarray


@dataclass(frozen=True, slots=True)
class SyntheticDataset:
    """Combined dataset with one split label per row and JSON-safe metadata."""

    features: np.ndarray
    targets: np.ndarray
    split: np.ndarray
    metadata: dict[str, Any]

    def get_split(self, name: str) -> DatasetSplit:
        """Select a split without exposing row-index bookkeeping to callers."""
        if name not in SPLIT_NAMES:
            raise ValueError(f"unknown dataset split: {name}")
        selected = self.split == name
        return DatasetSplit(self.features[selected], self.targets[selected])


def _sample_features(
    rng: np.random.Generator, bounds: InputBounds, count: int
) -> np.ndarray:
    lower = np.asarray([getattr(bounds, name).lower for name in FEATURE_NAMES])
    upper = np.asarray([getattr(bounds, name).upper for name in FEATURE_NAMES])
    return rng.uniform(lower, upper, size=(count, len(FEATURE_NAMES)))


def _simulate_targets(features: np.ndarray, config: SamplingConfig) -> np.ndarray:
    simulations = tuple(
        SimulationConfig(
            reactor=ReactorConfig(
                peak_temperature=row[0],
                residence_time=row[1],
                hydrogen_concentration=row[2],
            ),
            particle=ParticleConfig(
                diameter=row[3],
                initial_temperature=config.initial_temperature,
                initial_oxide_fraction=row[4],
            ),
            material=config.material,
            solver=config.solver,
        )
        for row in features
    )
    trajectory = simulate_batch(simulations)
    targets = np.column_stack(
        (
            np.asarray(trajectory.final_oxide_fraction),
            np.asarray(trajectory.maximum_temperature),
        )
    )
    if not np.isfinite(targets).all():
        raise ValueError("simulator produced non-finite targets; adjust sampling or solver settings")
    return targets


def generate_dataset(config: SamplingConfig) -> SyntheticDataset:
    """Sample inputs and generate all train, validation, test, and OOD targets."""
    if not isinstance(config, SamplingConfig):
        raise TypeError("config must be a SamplingConfig")

    rng = np.random.default_rng(config.seed)
    feature_splits = []
    target_splits = []
    split_labels = []
    sample_counts = {
        "train": config.train_samples,
        "validation": config.validation_samples,
        "test": config.test_samples,
        "ood": config.ood_samples,
    }
    for name, count in sample_counts.items():
        bounds = config.ood_bounds if name == "ood" else config.sampling_bounds
        features = _sample_features(rng, bounds, count)
        targets = _simulate_targets(features, config)
        feature_splits.append(features)
        target_splits.append(targets)
        split_labels.append(np.full(count, name))

    metadata = {
        "schema_version": 1,
        "synthetic": True,
        "feature_names": list(FEATURE_NAMES),
        "target_names": list(TARGET_NAMES),
        "feature_units": {
            "peak_temperature": "K",
            "residence_time": "s",
            "hydrogen_concentration": "mol m^-3",
            "diameter": "m",
            "initial_oxide_fraction": "1",
        },
        "target_units": {
            "final_oxide_fraction": "1",
            "maximum_temperature": "K",
        },
        "split_names": list(SPLIT_NAMES),
        "split_sizes": sample_counts,
        "sampling_config": asdict(config),
    }
    return SyntheticDataset(
        features=np.concatenate(feature_splits),
        targets=np.concatenate(target_splits),
        split=np.concatenate(split_labels),
        metadata=metadata,
    )


def save_dataset(dataset: SyntheticDataset, output_path: str | Path) -> Path:
    """Save arrays in NPZ and metadata in an adjacent JSON file."""
    output_path = Path(output_path)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    np.savez_compressed(
        output_path,
        features=dataset.features,
        targets=dataset.targets,
        split=dataset.split,
    )
    output_path.with_suffix(".json").write_text(
        json.dumps(dataset.metadata, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    return output_path


def load_dataset(input_path: str | Path) -> SyntheticDataset:
    """Load a dataset without enabling pickled NumPy objects."""
    input_path = Path(input_path)
    with np.load(input_path, allow_pickle=False) as arrays:
        features = arrays["features"].copy()
        targets = arrays["targets"].copy()
        split = arrays["split"].copy()
    metadata = json.loads(input_path.with_suffix(".json").read_text(encoding="utf-8"))
    return SyntheticDataset(features, targets, split, metadata)
